INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '31b06f81-f037-57d3-8797-7a5e64b9ceb4'::uuid, 'e7547977-2ccd-562d-aa0c-59d67752f5ba'::uuid, 'Goldstar Business Center', '### Goldstar Business Center L''adresse professionnelle qu''il vous faut à Marrakech Goldstar Business Center est un nouveau projet de standing en cours de construction, idéalement situé au cœur du prestigieux quartier Majorelle à Marrakech. Conçu pour accueillir aussi bien des plateaux de bureaux modulables que des locaux commerciaux spacieux avec mezzanine, ce centre d''affaires s''adresse aux professionnels en quête d''un cadre de travail moderne, stratégique et rentable. Livraison prévue: fin 2026 ### Pourquoi choisir Goldstar Business Center? Un projet pensé pour les entrepreneurs, startups, investisseurs et commerçants désireux d''implanter leur activité dans une zone à fort potentiel économique et à haute visibilité. ### Caractéristiques du projet: - Emplacement premium: 32 Boulevard Allal Al Fassi, Majorelle, Marrakech - Résidence R+5 aux finitions soignées - Surfaces variées: - Plateaux bureaux: à partir de 46 m² - Magasins avec mezzanine: dès 173 m² (97,7 m² + 75,5 m²) - Ascenseur moderne desservant tous les niveaux - 2 sous-sols avec parkings et locaux de service - Climatisation centralisée pour un confort optimal - Prix attractif: à partir de 13.000 DH/m², une opportunité rare dans ce secteur ### Un emplacement stratégique au cœur de Marrakech - À 2 km de la célèbre place Jamaa El-Fna - À 1,4 km du centre commercial Carré Eden - À proximité immédiate de Carrefour et de nombreux commerces - Accès rapide aux grands axes routiers ### Un investissement sûr et rentable Que vous cherchiez à implanter vos bureaux, ouvrir une enseigne, ou investir dans l''immobilier professionnel à fort rendement, Goldstar Business Center coche toutes les cases: emplacement premium, accessibilité optimale, infrastructures modernes, et prix compétitif. #### Dernières unités disponibles - Saisissez l''opportunité dès maintenant!', 'Marrakech', 'Majorelle', '32 BD Allal Al Fassi, Majorelle, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'commercial_bureaux', 'commercial_bureaux', 'en_construction', 'en_commercialisation', 55, '2026-12', NULL, 'https://media.chridari.ma/ce1d021c-93d7-499d-a8aa-930759fafeed/images/01JZANTEW3EPVZJM5N8NR2RHEW-medium.jpg', $j$["https://media.chridari.ma/ce1d021c-93d7-499d-a8aa-930759fafeed/images/01JZANTEW3EPVZJM5N8NR2RHEW-medium.jpg", "https://media.chridari.ma/63f3d0e8-4e89-4c28-85d3-24bd50af2986/images/01JZANTG483M9QCF6JPND3DM1Y-medium.jpg", "https://media.chridari.ma/1e305c55-44fc-44d7-9409-25ea75de91dd/images/01JZANTFNDE8SCA5K3780SG1XP-medium.jpg", "https://media.chridari.ma/451a86ce-c48c-4016-80ed-eea0f229280f/images/01JZANTGCXQH2NCH67P6C52BDV-medium.jpg"]$j$::jsonb, 'Plateau bureau | Local commercial', 'Climatisation ,  Balcon ,  Ascenseur ,  Concierge ,  Parking ,  Terrasse ,  Issue de secours', 'Centre commercial ,  Mosquée ,  École ,  Banque ,  Café ,  Salle de sport ,  Supermarché', false, 598000.0, 598000.0, 900000.0, 'MAD', '46 – 186 m2', 'e7547977-2ccd-562d-aa0c-59d67752f5ba', 'Goldstar Résidences', 'https://chridari.ma/fr/promoters/goldstar-residences-fzdp4', $j$[{"id": "", "name": "RIDGENIE Génie civil - Bureau d'études des projets de construction", "role": "Partenaire / intervenant", "logo": "", "website": ""}, {"id": "", "name": "Bureau d'études techniques KMA CONSULT", "role": "Partenaire / intervenant", "logo": "", "website": ""}, {"id": "", "name": "Bureau d'études techniques METR ETUDE ET CONSEIL", "role": "Partenaire / intervenant", "logo": "", "website": ""}, {"id": "", "name": "C.T.R. (Construction Et Travaux Routiers)", "role": "Partenaire / intervenant", "logo": "", "website": ""}, {"id": "", "name": "MAITRE² ENTREPRISE GENERALE", "role": "Partenaire / intervenant", "logo": "", "website": ""}, {"id": "", "name": "FCVC MAROC", "role": "Partenaire / intervenant", "logo": "", "website": ""}, {"id": "", "name": "Tikida Aluminium", "role": "Partenaire / intervenant", "logo": "", "website": ""}, {"id": "", "name": "OKTI travaux", "role": "Partenaire / intervenant", "logo": "", "website": ""}]$j$::jsonb, $j${"source_project_id": "31b06f81-f037-57d3-8797-7a5e64b9ceb4", "chridari_ref": "m3qyxc", "projet_id_legacy": "CHR-PRJ-m3qyxc", "reference_annonce": "MA433497", "url_source": "https://chridari.ma/fr/projects/goldstar-business-center-plateau-bureau-local-commercial-marrakech-m3qyxc", "seed_batch": "promoteurs_full_sifarah"}$j$::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.projects x WHERE x.id = '31b06f81-f037-57d3-8797-7a5e64b9ceb4'::uuid OR x.attributes->>'source_project_id' = '31b06f81-f037-57d3-8797-7a5e64b9ceb4');
