INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '8772d1f0-6d4b-5de0-b083-c9b608436e4e'::uuid, 'e91e0170-3918-52e1-b337-fd503a06c989'::uuid, 'Nour Horizon', '### Nour Horizon – Un cadre de vie harmonieux à Targa, Marrakech Le projet Nour Horizon s''inscrit dans un environnement résidentiel calme et recherché, au cœur du quartier Targa à Marrakech. Conçu pour offrir un équilibre parfait entre sérénité et dynamisme urbain, ce projet propose un cadre de vie agréable, idéal pour les familles comme pour les actifs en quête de confort et de stabilité. Situé dans une zone en plein développement, Nour Horizon bénéficie d''un environnement structuré, moderne et bien organisé, où la qualité de vie est au centre de chaque détail. L''atmosphère paisible du quartier favorise le bien-être quotidien, tout en restant connectée à l''énergie de la ville ocre. ### Un environnement pensé pour le quotidien - Quartier résidentiel calme et sécurisé - Ambiance familiale et conviviale - Cadre urbain moderne et bien aménagé - Environnement propice à la tranquillité et à la stabilité Nour Horizon représente une opportunité idéale pour s''installer dans un cadre harmonieux, où confort, sérénité et modernité se rencontrent au quotidien.', 'Marrakech', 'Targa', 'À côté de l''hôtel Zyphyr,, Targa, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residentiel', 'pret_a_livrer', 'en_commercialisation', 90, '2028-12', NULL, 'https://media.chridari.ma/a26714b1-041a-4158-bd9b-b7685cb8fffa/images/01KDZM08E50JFSREYVMJGT3AQ2-medium.jpg', $j$["https://media.chridari.ma/a26714b1-041a-4158-bd9b-b7685cb8fffa/images/