INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '1fb6a513-b96c-5e4d-b117-382f4f740a31'::uuid, '51567ad8-86f8-5ddd-a646-0ae429b148d5'::uuid, 'Rosa Parc', '### Rosa Parc - Confort et modernité au cœur de Mohammedia Situé en plein centre-ville de Mohammedia, Rosa Parc est un projet du Groupe Allali conçu pour répondre aux besoins d''une clientèle exigeante. Cette résidence moderne se distingue par son emplacement stratégique au sein du quartier administratif et sa conception contemporaine. Appartement disponible : - Superficie: 106 m² - Disposition: 1 chambre + salon - Salle de bain: 1 - Prix/m²: À partir de 13 000 dh/m² - Statut: Livraison immédiate ### Atouts : - Parking au sous-sol - Sécurité 24h/7j - Syndic professionnel ### À proximité : - Parc Floral de Mohammedia - Sortie d''autoroute vers Casablanca - Écoles, cafés, restaurants - Supermarchés, plages, pharmacies Que ce soit pour y vivre ou pour investir, Rosa Parc est une opportunité à ne pas manquer.', 'Mohammedia', 'Wafa', 'Rue Ibn Rochd, Wafa, 28800 Mohammedia', '28800', 'MA', NULL, NULL, 'immobilier', 'mixte', 'mixte', 'pret_a_livrer', 'en_commercialisation', 90, NULL, NULL, 'https://media.chridari.ma/1ff87378-139d-4ce7-b64d-54e478ec0189/images/01JY1BHT3SSC1259H09BGRCQC7-medium.jpg', $j$["https://media.chridari.ma/1ff87378-139d-4ce7-b64d-54e478ec0189/images/01JY1BHT3SSC1259H09BGRCQC7-medium.jpg", "https://media.chridari.ma/6af55763-50ac-488e-9a15-57c746158065/images/01JY1BHRAG858RX5AHHQKXGJ0Q-medium.jpg", "https://media.chridari.ma/83ddee46-e67f-454e-8d0e-25221164bc5d/images/01JY1BHS5VD603XHVGNV4JB40V-medium.jpg"]$j$::jsonb, 'Appartement'