INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '26a179de-e0eb-5326-bcdb-89d058ca5fb9'::uuid, '252cdc9e-3118-5c8d-bdac-2d5032bb16a5'::uuid, 'Amiral Immobilier', 'Amiral Immobilier est un nouveau projet, idéalement situé au cœur de Guéliz, Marrakech. Ce complexe moderne résidentiel et commercial propose : - Appartements à vendre de 2 à 3 chambres, allant de 45 à 97 m², avec des finitions haut de gamme telles que sol en marbre, cuisine équipée, climatisation, dressings, cheminées, et bien plus — parfait pour les acheteurs recherchant des appartements de luxe à Marrakech. - Plateaux bureaux à louer ou à vendre de 94 à 120 m², à partir de 975 000 MAD, idéal pour les entreprises en quête de locaux commerciaux premium à Guéliz. - Commerces et espaces commerciaux de 35 à 94 m², à partir de 577 500 MAD, adaptés aux entrepreneurs cherchant des espaces commerciaux en centre-ville de Marrakech. Le projet se compose de trois blocs : - Bloc A : en phase de finition. - Blocs B et C : en cours de gros œuvre. La livraison est prévue pour 2026, une excellente opportunité pour un investissement immobilier neuf à Marrakech. ### Localisation - Adresse : Avenue Hassan II, Guéliz, Marrakech 40000 — un quartier très prisé pour son accessibilité et ses commodités urbaines. - À proximité : gare ONCF, centre commercial Carré Eden, Marrakech Plaza, Théâtre Royal, un atout majeur pour la localisation premium à Guéliz. ### Équipements - Piscine moderne pour la détente des résidents. - Espaces verts paysagers offrant un cadre urbain paisible. - Résidence fermée et sécurisée avec service de conciergerie 24h/24, garantissant confort et sécurité. - Ascenseurs et parkings en sous-sol, essentiels pour la vie urbaine.', 'Marrakech', 'Guéliz', 'Avenue Hassan II, Guéliz, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'mixte', 'mixte', 'en_construction', 'en_commercialisation', 55, '2026-05', NULL, 'https://media.chridari.ma/b0d02504-2c45-4acf-b08c-c2b26fab0e86/images/01JWE2T8TJ86B8RE18K7ZSV9JY-medium.jpg', $j$["https://media.chridari.ma/b0d02504-2c45-4acf-b08c-c2b26fab0e86/images/01JWE2T8TJ86B8RE18K7ZSV9JY-medium.jpg", "https://media.chridari.ma/7b0577be-e9c0-4956-aa73-deae3cdfdb0c/images/01JWE2T9C674PHG8QV4V6519HS-medium.jpg", "https://media.chridari.ma/cea39ffe-d28a-49dc-b70b-47fbc94356fb/images/01JWE2T9ZKQTF2EH6SS98MSMZV-medium.jpg", "https://media.chridari.ma/37c287fa-0ace-41fb-a52e-c4bb16fa6099/images/01JWE2TA5PJ38ST17G5JS6QJYB-medium.jpg", "https://media.chridari.ma/3468810a-e3ae-477f-aa87-6371a94f7c83/images/01JWE2TAET9AK3ZQ7MF4NMDVK7-medium.jpg", "https://media.chridari.ma/093df996-15ad-48eb-baeb-42cca7daf332/images/01JWE2TAM94E9WB29G8RFWNP3B-medium.jpg", "https://media.chridari.ma/081a60fe-31de-4d81-9913-3f707ea7bd88/images/01JWE2TAT8ZE8E1QR6VXNND862-medium.jpg", "https://media.chridari.ma/1c5d6fab-618d-4a6b-8682-1ee9e374fcc6/images/01JWE2TB050DH7FRJMQQ1QYHSY-medium.jpg", "https://media.chridari.ma/e2d22af7-48ec-4b85-986f-2761d8654889/images/01JWE2TB9XRACVTHR7C3VEBJRR-medium.jpg"]$j$::jsonb, 'Appartement | Plateau bureau | Local commercial', 'Piscine ,  Parking ,  Ascenseur ,  Climatisation ,  Système de sécurité ,  Dressing ,  Cuisine équipée ,  Chauffage ,  Vue sur les montagnes ,  Concierge', 'École ,  Gare ,  Centre commercial ,  Mosquée', false, 522000.0, 522000.0, 975000.0, 'MAD', '35 – 120 m2', '252cdc9e-3118-5c8d-bdac-2d5032bb16a5', 'Groupe Arwa', 'https://chridari.ma/fr/promoters/groupe-arwa-p3bwj', $j$[]$j$::jsonb, $j${"source_project_id": "26a179de-e0eb-5326-bcdb-89d058ca5fb9", "chridari_ref": "js71i", "projet_id_legacy": "CHR-PRJ-js71i", "reference_annonce": "MA1