INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '7de7ac12-37ed-5d4b-9251-41088af2d0e5'::uuid, '252cdc9e-3118-5c8d-bdac-2d5032bb16a5'::uuid, 'Caprice Hivernage', 'Caprice Hivernage - Investissez dans l''Excellence à Marrakech Niché au cœur du prestigieux quartier Hivernage à Marrakech, Caprice Hivernage est une résidence d''exception conçue pour répondre aux plus hautes exigences du confort moderne. Ce projet en R+5 combine design élégant, emplacement premium, et technologies intelligentes pour une expérience de vie et de travail unique. #### Bureaux Professionnels Haut Standing Caprice Hivernage propose des plateaux bureaux modernes, parfaits pour les professionnels à la recherche d''un cadre de travail inspirant et accessible: - Surfaces disponibles : de 58 à 106 m² - Prix à partir de 1.160.000 DH - Espaces lumineux, modulables et prêts à être personnalisés Idéal pour installer votre activité au sein d''un quartier dynamique, proche de toutes les commodités. #### Locaux Commerciaux Prestigieux Développez votre commerce dans un emplacement stratégique, à fort passage piéton: - Superficie : 133 m² - Prix à partir de 5.500.000 DH - Visibilité exceptionnelle dans un quartier vivant et recherché Une opportunité rare pour les investisseurs et les entrepreneurs en quête d''un local commercial à Marrakech. #### Résidence Premium & Équipements Caprice Hivernage n''est pas qu''un simple projet immobilier, c''est une expérience résidentielle et professionnelle haut de gamme: - Résidence fermée et sécurisée 24h/24 - Piscine luxueuse et espaces verts paysagés - Ascenseurs modernes & parkings en sous-sol - Finitions en carrelage et marbre, interphones et cuisines équipées - Système Smart Home pour un contrôle à distance de votre espace #### Emplacement de Rêve à Marrakech Situé à quelques pas des incontournables de la ville : M Avenue, gare ONCF, Menara Mall, mosquées, écoles et plus encore.', 'Marrakech', 'Hivernage', 'Intersection de la rue Ezzoubair Ben El Aouame et de la rue Ibn El Qadi, Hivernage, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'mixte', 'mixte', 'en_construction', 'en_commercialisation', 55, '2025-12', NULL, 'https://media.chridari.ma/3ce21145-22f4-491e-bd83-684c093cb6fc/images/01JWEDH3K24QZTC60V4FZXQRK8-medium.jpg', $j$["https://media.chridari.ma/3ce21145-22f4-491e-bd83-684c093cb6fc/images/01JWEDH3K24QZTC60V4FZXQRK8-medium.jpg", "https://media.chridari.ma/a9925060-73ed-4635-95c2-331da6d7ce79/images/01JWEF1D8GW14V9SXQJ3ZF5DJW-medium.jpg", "https://media.chridari.ma/5a8edf0a-0377-44ab-a463-200e6aeffc26/images/01JWEDH42644F65Y6M3EFH6WE2-medium.jpg", "https://media.chridari.ma/81579e21-9c38-4efc-a05a-8aeb6392593c/images/01JWEF1DZXD81VN0D8F7XAXAM1-medium.jpg", "https://media.chridari.ma/b44a1503-dc5a-4bb6-b1b1-0e16cb8babee/images/01JWEDH4F08TJZZMXE2WC8RP0A-medium.jpg"]$j$::jsonb, 'Appartement | Plateau bureau | Local commercial', 'Parking ,  Climatisation ,  Chauffage ,  Balcon ,  Système de sécurité', 'Gare ,  Centre commercial ,  École ,  Mosquée', false, 460000.0, 460000.0, 5500000.0, 'MAD', '37 – 133 m2', '252cdc9e-3118-5c8d-bdac-2d5032bb16a5', 'Groupe Arwa', 'https://chridari.ma/fr/promoters/groupe-arwa-p3bwj', $j$[]$j$::jsonb, $j${"source_project_id": "7de7ac12-37ed-5d4b-9251-41088af2d0e5", "chridari_ref": "4a5c0", "projet_id_legacy": "CHR-PRJ-4a5c0", "reference_annonce": "MA149843", "entreprises_construction": "Groupe Arwa Immobilier (promoteur-constructeur intégré)", "equipe_realisation_mentions": "Entreprise / construction: Groupe Arwa Immobilier se présente comme groupe de construction et de promotion (LinkedIn company)", "url_sourc