INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '9edfab76-1529-53bb-b5f0-5e8dc863dce7'::uuid, 'eea0a636-63d3-5a52-bbb7-9111d2a642cf'::uuid, 'LuxLiving', 'Situé au cœur de Mers Sultan, à Casablanca, le projet LuxLiving incarne une nouvelle génération d''espaces résidentiels et professionnels. À quelques pas du GS La Résidence et des enseignes comme KFC, Carrefour et McDonald''s, ce projet bénéficie d''un emplacement stratégique et vivant. LuxLiving propose: - Studios modernes de 34 à 99 m² - Bureaux fonctionnels de 39 à 113 m² - À partir de 800,000 MAD, parking et box inclus ### Équipements inclus: - Climatisation centralisée - Cuisine équipée - Ascenseurs - Vidéo-surveillance - Rooftop & service d''accueil (bureaux) - Parking et box titrés Livraison imminente : août 2025 Un choix idéal pour habiter ou investir dans un secteur dynamique et bien desservi.', 'Casablanca', 'Mers Sultan', 'LuxLiving, Mers Sultan, 20006 Casablanca', '20006', 'MA', NULL, NULL, 'immobilier', 'mixte', 'mixte', 'pret_a_livrer', 'en_commercialisation', 90, '2025-08', NULL, 'https://media.chridari.ma/1b33c3e4-b4b3-4d39-b92b-a651c09407df/images/01JWZN92A6SN3DMT6F50BT5W29-medium.jpg', $j$["https://media.chridari.ma/1b33c3e4-b4b3-4d39-b92b-a651c09407df/images/01JWZN92A6SN3DMT6F50BT5W29-medium.jpg", "https://media.chridari.ma/3cc0cb35-a0e3-4fb1-9842-ba872c180724/images/01JWZN92PA4XSTNVZ7B2Y78A56-medium.jpg", "https://media.chridari.ma/7d59f287-3edf-45dc-95c0-92a0a1068dde/images/01JWZN930ZG0F9NM0DED8PBEF9-medium.jpg", "https://media.chridari.ma/816ea8da-a148-443c-b9bb-a592b0dc1013/images/01JWZN93AM5MF3N55TJKXHJ50R-medium.jpg", "https://media.chridari.ma/541b6565-d90d-4372-ab61-0d6e68218605/images/01JWZN93KF34P5DP9JJJ4T3N31-medium.jpg"]$j$::jsonb, 'Studio | Plateau bureau', 'Parking ,  Cuisine équipée ,  Climatisation ,  Système de sécurité', 'École ,  Station de tramway ,  Clinique ,  Commissariat ,  Centre commercial', false, 800000.0, 800000.0, 950000.0, 'MAD', '34 – 113 m2', 'eea0a636-63d3-5a52-bbb7-9111d2a642cf', 'Irmo Business', 'https://chridari.ma/fr/promoters/irmo-business-yk673', $j$[]$j$::jsonb, $j${"source_project_id": "9edfab76-1529-53bb-b5f0-5e8dc863dce7", "chridari_ref": "kxh2k", "projet_id_legacy": "CHR-PRJ-kxh2k", "reference_annonce": "CA465195", "url_source": "https://chridari.ma/fr/projects/luxliving-studio-plateau-bureau-casablanca-kxh2k", "chambres_min": "1", "chambres_max": "1", "seed_batch": "promoteurs_full_sifarah"}$j$::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.projects x WHERE x.id = '9edfab76-1529-53bb-b5f0-5e8dc863dce7'::uuid OR x.attributes->>'source_project_id' = '9edfab76-1529-53bb-b5f0-5e8dc863dce7');
INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '873b30c8-9ba6-56fa-8d95-373cdcfa9818'::uuid, '06c78006-b100-5480-b82a-83ac16fbe902'::uuid, 'Lotissement Kacem', 'Le Lotissement Kacem est un nouveau quartier résidentiel et commercial stratégiquement implanté dans le dynamique secteur de Bouakkaz à Marrakech, à cheval entre M''hamid Sud et Chrifia. Niché dans une zone en plein essor, ce projet propose des lots prêts à bâtir allant de 80 à 119 m², idéals pour des maisons modernes et des projets commerciaux de proximité. Accessibilité optimale: - 2 voies aménagées de 15 m - Prolongement d''une artère principale de 20 m - 5 points d''accès pensés pour fluidifier la circulation Entouré d''infrastructures modernes, Lotissement Kacem offre un mode de vie complet. Vous y trouverez: - Écoles et espaces éducatifs - Infrastructures culturelles et artistiques - Centres de shopping et loisirs - Services de santé à proximité À proximité immédiate: - Parc aquatique - Golf - Piscine couverte - Centre culturel - Théâtre Sa proximité avec les pôles essentiels de la ville en fait un emplacement de choix: 3 minutes de l''aéroport, 12 minutes du Morocco Mall, et à quelques minutes du centre-ville. Infrastructures internes: - Espaces verts - Places de parking - Aire de jeux - Équipement privé - Deux postes transformateurs Et pour les amateurs de paysages, une vue imprenable sur les montagnes de l''Atlas vient sublimer le quotidien. Offre limitée: Plus que quelques lots commerciaux R+2 de 80 m² à 780 000 DHS.', 'Marrakech', 'Bouakkaz', 'Lotissement Kacem Rue N°4 M''Hamid Sud, Bouakkaz, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'lotissement', 'lotissement', 'sur_plan', 'en_commercialisation', 15, '2026-03', NULL, 'https://media.chridari.ma/ee25bbdb-cc2c-4cb7-84f3-d66840dc5c42/images/01JVY77DNVP80YVPGK9F39CGJC-medium.jpg', $j$["https://media.chridari.ma/ee25bbdb-cc2c-4cb7-84f3-d66840dc5c42/images/01JVY77DNVP80YVPGK9F39CGJC-medium.jpg", "https://media.chridari.ma/9fd99899-18dc-4018-90c4-56b97ae172ab/images/01JVY7BDHJGVTW9GEGDXQW2HC3-medium.jpg", "https://media.chridari.ma/dfd1ff68-bb13-4917-ad87-657182b41970/images/01JVY7Y41TSPKA0220NCT8D6X9-medium.jpg"]$j$::jsonb, 'Terrain', 'Vue sur les montagnes ,  Parking ,  Aire de jeux ,  Jardin', 'École ,  Aéroport ,  Mosquée ,  Hôpital ,  Centre commercial ,  Salle de sport', false, 780000.0, 600000.0, 780000.0, 'MAD', '80 – 119 m2', '06c78006-b100-5480-b82a-83ac16fbe902', 'Istihlal', 'https://chridari.ma/fr/promoters/istihlal-ijou', $j$[]$j$::jsonb, $j${"source_project_id": "873b30c8-9ba6-56fa-8d95-373cdcfa9818", "chridari_ref": "7iru9", "projet_id_legacy": "CHR-PRJ-7iru9", "reference_annonce": "MA231298", "url_source": "https://chridari.ma/fr/projects/lotissement-kacem-lot-de-terrain-marrakech-7iru9", "seed_batch": "promoteurs_full_sifarah"}$j$::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.projects x WHERE x.id = '873b30c8-9ba6-56fa-8d95-373cdcfa9818'::uuid OR x.attributes->>'source_project_id' = '873b30c8-9ba6-56fa-8d95-373cdcfa9818');
INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT 'cf79d4c2-db44-524c-8995-90314652c6f4'::uuid, 'b36f5821-0db7-5f73-b06e-4d4135545c93'::uuid, 'Lilas Park', '### Lilas Park un cadre de vie moderne et apaisant Situé dans le quartier dynamique de Aïn Sebaâ à Casablanca, Lilas Park offre un environnement idéal pour celles et ceux qui recherchent équilibre, confort et accessibilité au quotidien. ### Un emplacement stratégique Le projet bénéficie d''une localisation privilégiée, à proximité des grands axes reliant les différents quartiers de la ville. Cette situation permet de profiter d''un accès fluide tout en restant dans un cadre résidentiel calme et agréable. ### Un environnement harmonieux Entouré d''espaces ouverts et d''un cadre en pleine évolution, Lilas Park propose une atmosphère propice au bien-être. La présence d''espaces naturels à proximité apporte une touche de fraîcheur et favorise un style de vie sain et équilibré. ### Une vie quotidienne facilitée Vivre à Lilas Park, c''est choisir un quartier en plein essor, où tout est pensé pour simplifier le quotidien. Que ce soit pour le travail, les études ou les loisirs, tout est accessible rapidement. ### Un projet pensé pour tous Ce projet s''adresse aussi bien aux familles qu''aux jeunes actifs ou aux investisseurs à la recherche d''un environnement moderne et prometteur, au cœur d''un secteur en constante évolution.', 'Casablanca', 'Aïn Sebaâ', 'Près du zoo, Km 9 Route de Rabat, Aïn Sebaâ, 20100 Casablanca', '20100', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residentiel', 'en_construction', 'en_commercialisation', 55, '2027-12', NULL, '