INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '1935bfef-b304-5f9f-b7f1-bb01084cca61'::uuid, '2dcb2ad1-80f8-5e26-b48f-7e86ee5763e8'::uuid, 'Les Iris I', 'Bienvenue à LES IRIS I, une résidence moderne qui redéfinit l''art de vivre à Mohammedia. Située au cœur de Beni Yakhlef, cette adresse allie élégance architecturale, confort quotidien et opportunités d''investissement uniques. Les appartements, de 73 à 110 m² (dès 9 000 DH/m²), sont conçus pour offrir des espaces lumineux et bien agencés, idéals pour les familles en quête de sérénité et de modernité. Des bureaux fonctionnels, de 38 à 90 m² (dès 11 500 DH/m²), viennent compléter le projet, parfaits pour entrepreneurs et professionnels désirant évoluer dans un cadre stimulant. Enfin, les espaces commerciaux, de 24 à 153 m² (dès 15 000 DH/m²), garantissent visibilité et attractivité, une valeur sûre pour tout investissement. Côté confort, la résidence met à votre disposition: - Balcons & terrasses avec vue - Parking & ascenseur - Piscine, aire de jeux et conciergerie - Cuisine équipée & dressing intégré Statut: Prêt à livrer fin octobre LES IRIS I n''est pas seulement un projet immobilier, c''est un mode de vie alliant confort, modernité et rentabilité.', 'Mohammedia', 'Béni Yakhlef', 'Boulevard Sebta, Béni Yakhlef, 28815 Mohammedia', '28815', 'MA', NULL, NULL, 'immobilier', 'mixte', 'mixte', 'pret_a_livrer', 'en_commercialisation', 90, '2025-10', NULL, 'https://media.chridari.ma/63cbdfd3-8b11-47ff-8ff7-1c266f233906/images/01K5GQQ5AXQ58SEEZC2W1R7K93-medium.jpg', $j$["https://media.chridari.ma/63cbdfd3-8b11-47ff-8ff7-1c266f233906/images/01K5GQQ5AXQ