INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '6b11ae4b-80e2-53f8-9d8b-1662c5f194df'::uuid, '845177df-1fc1-524b-95c0-984f7976c4ba'::uuid, 'Studios neufs à Roches Noires', 'Studios neufs à Roches Noires, Casablanca - Prêts à livrer Découvrez une opportunité unique d''investissement immobilier à Casablanca avec ces studios neufs idéalement situés dans le quartier recherché de Roches Noires. Alliant confort moderne et emplacement stratégique, ce projet est parfait pour les primo-accédants, les jeunes actifs ou les investisseurs à la recherche d''un bon rendement locatif. ### Localisation idéale Situé à la Boulevard Moulay Ismail, ce projet bénéficie d''un accès facile aux transports, aux commerces et aux services essentiels. Vous êtes à quelques minutes du centre-ville de Casablanca tout en profitant d''un quartier calme et résidentiel. ### Caractéristiques du projet - Studios modernes de 40 m² à 54 m² - 1 salle de bain par appartement - Livraison fin août – Projet prêt à livrer - Prix à partir de 620 000 DH - À partir de 15 500 DH/m² - Parking sécurisé - Ascenseur - Climatisation - Sécurité assurée ### Un investissement rentable à Casablanca Avec un prix attractif et une demande forte en studios à Casablanca, ce projet représente une excellente opportunité pour : - L''investissement locatif - Une première acquisition - Un pied-à-terre fonctionnel et moderne Ne ratez pas cette chance d''acquérir un studio neuf à Roches Noires, l''un des quartiers montants de Casablanca. Offrez-vous un bien immobilier de qualité, livré rapidement, avec tout le confort moderne.', 'Casablanca', 'Roches Noires', 'Boule