INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '5612c777-e38f-530d-adc3-ba4b2c918447'::uuid, '960d6448-5e27-564c-b880-feaf542e8346'::uuid, 'Sunset Valley', 'Sunset Valley - Un havre de paix aux portes de la ville Situé à seulement 20 minutes du centre-ville de Marrakech, Sunset Valley Marrakech vous invite à découvrir un domaine exclusif composé de 10 villas de luxe, nichées dans un écrin de verdure avec une vue imprenable sur les montagnes de l''Atlas. ### Points forts du projet - Vue panoramique sur l''Atlas - Environnement naturel paisible - Jardins privatifs et piscine individuelle - 5 suites avec salles de bain privatives - Finitions haut de gamme et espaces spacieux ### Équipements haut standing - Piscine privée pour chaque villa - Hammam traditionnel intégré - Terrasse de 150 m² avec vue dégagée - Cheminée fonctionnelle pour des soirées cosy - Climatisation centralisée & double vitrage - Cuisine moderne entièrement équipée - Grande salle de réception - Résidence sécurisée avec service 24h/24 ### Un mode de vie prestigieux Sunset Valley Marrakech incarne un art de vivre unique, où luxe, confort moderne et harmonie avec la nature se rencontrent pour offrir une expérience résidentielle exceptionnelle.', 'Marrakech', 'Tassoultante', 'Route de l''Ourika, Tassoultante, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residentiel', 'pret_a_livrer', 'en_commercialisation', 90, '2026-02', NULL, 'https://media.chridari.ma/9f7f81d7-8e87-4d26-836f-88359fc3f79e/images/01JW8P5SB21ZRW8KWGMM6ACEXF-medium.jpg', $j$["https://media.chridari.ma/9f7f81d7-8e87-4d26-836f-88359fc3f79e/im