INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT 'e8ef3874-6632-51a6-96c6-bcb10cb772a5'::uuid, '4551e559-7852-54b2-8c4b-bfa2c585d710'::uuid, 'Casa Road', 'Casa Road - Marrakech Statut : En construction | Prix à partir de : 665 000 MAD | Prix par m² : 16 000 MAD Bienvenue à Casa Road, l''un des projets immobiliers les plus attendus à Marrakech. Situé stratégiquement sur le Boulevard Abdelkrim El Khattabi, ce projet propose des appartements, studios, duplex, triplex et magasins, conçus pour ceux qui recherchent confort, design moderne et opportunités d''investissement intelligentes. Emplacement privilégié : Vivez au cœur de Marrakech, à proximité de cafés, banques, cinémas, écoles, parcs, mosquées, supermarchés et tous les services essentiels. Profitez d''un accès facile à l''autoroute, pour tous vos déplacements. Pourquoi choisir Casa Road? - Vie moderne : Des espaces spacieux et une architecture contemporaine pour un confort optimal. - Potentiel d''investissement : Un emplacement stratégique qui garantit une valorisation à long terme. - Style de vie et commodité : Tout ce dont vous avez besoin à quelques minutes. Que vous soyez premier acheteur, investisseur ou famille, Casa Road est conçu pour répondre à toutes vos attentes. Profitez d''un style de vie où chaque détail est pensé, et sécurisez votre bien immobilier de rêve à Marrakech dès aujourd''hui. Ne tardez pas, votre futur logement ou investissement vous attend !', 'Marrakech', 'Koudiat Laabid', 'Boulevard Abdelkrim El Khattabi, Koudiat Laabid, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'mixte', 'mixte', 'en_construction', 'en