INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '6857be52-c999-5272-a447-3252e6d699c1'::uuid, '5854805e-5245-50a6-b5ee-2c68d98c39f4'::uuid, 'Résidence la Pensée', 'Résidence la Pensée est un projet résidentiel premium situé dans le quartier Beauséjour à Casablanca. Conçu pour offrir confort et élégance, il propose des appartements spacieux de 2 et 3 chambres avec des surfaces à partir de 70 m², incluant de grandes terrasses pour les appartements de 2 chambres. Idéalement localisé près des centres d''affaires et de loisirs tels que CFC et AERIA MALL, ce projet combine vie moderne et accessibilité. Les résidents bénéficient d''un environnement sécurisé avec une sécurité 24h/24 et un ensemble d''équipements haut de gamme. ### Points forts: - Appartements spacieux a partir de 70 m² - Grandes terrasses pour les appartements 2 chambres - Service de conciergerie - Climatisation pour un confort optimal - Ascenseur - Parking sécurisé - Sécurité 24h/24 Vivez une expérience urbaine d''exception avec Résidence la Pensée, où qualité, emplacement et style de vie s''harmonisent pour un chez-soi d''exception.', 'Casablanca', 'Beauséjour', 'Rue Erraihane, Beauséjour, 20026 Casablanca', '20026', 'MA', NULL, NULL, 'immobilier', 'mixte', 'mixte', 'pret_a_livrer', 'en_commercialisation', 90, NULL, NULL, 'https://media.chridari.ma/74aff489-b873-476a-94a6-c6c16cf80551/images/01JWZXZGTT2YEECKM88796ESHD-medium.jpg', $j$["https://media.chridari.ma/74aff489-b873-476a-94a6-c6c16cf80551/images/01JWZXZGTT2YEECKM88796ESHD-medium.jpg", "https://media.chridari.ma/a5e3230a-3d6a-4b3a-a537-6c020a68cb1c/images/01JWZXZG6P57K5V3Y0PN21G