INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '293b4880-aef2-58ea-85c3-afeae557567b'::uuid, '369cc4b3-880f-502a-9769-f8d1a1e0d6b8'::uuid, 'Résidence Rumaisa', 'Résidence Rumaisa - Un cadre de vie d''exception à Tanger Située dans le prestigieux quartier El Moujahidine, la Résidence Rumaisa se distingue par son architecture moderne et ses finitions luxueuses. Ce projet résidentiel haut standing, prêt à livrer, vous propose des appartements spacieux et lumineux avec des matériaux de qualité supérieure. #### Caractéristiques des appartements: - Superficie à partir de 111 m² - Prix à partir de 14 000 DH/m² - 3 chambres, salon, balcon ou terrasse - Cuisine équipée, salles de bain modernes, dressing - Sol en marbre, parquet dans les chambres - Isolation thermique et phonique - Cuisine importé d''Allemagne - 4 ascenseurs et parking en sous-sol - Parking sous sol titré - Près installation climatisation - Appartments disponible immédiatement #### Environnement & proximité: - Situé sur la desserte du Golf El Moujahidine - À proximité de: centre commercial, écoles, universités, hôpitaux, cafés, salle de sport, hammam, plage, forêt... Un lieu idéal pour un cadre de vie confortable ou un investissement sûr à Tanger.', 'Tanger', 'Moujahidine', 'Avenue Desserte Qur Golf, Moujahidine, 90000 Tanger', '90000', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residentiel', 'pret_a_livrer', 'en_commercialisation', 90, NULL, NULL, 'https://media.chridari.ma/f18015ac-95e9-41be-838b-a5e3210b4b39/images/01JZX3WTEPNS1BDSCYHJGMRDT0-medium.jpg', $j$["https://media.chridari.ma/f18015ac-95e9-41be-838b-a5e3210b4b39/images/01J