INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '2e936673-1ff2-51ce-b7a9-7026179bf1a8'::uuid, '41a5b3a6-d10a-5bcb-a0fe-4f05e0542ed2'::uuid, 'Résidence Rania 6', '### Résidence Rania 6 Un cadre de vie équilibré à Casablanca La Résidence Rania 6 est idéalement située au quartier Victoria, au sein du lotissement Annasr, offrant un environnement résidentiel calme et agréable. ### Un environnement serein Le projet a été pensé pour garantir une qualité de vie optimale, avec: - Une ambiance paisible et organisée - Un cadre propice au repos - Un équilibre entre tranquillité et vie urbaine ### Une localisation pratique Son emplacement facilite les déplacements quotidiens et permet de profiter pleinement de la dynamique de Casablanca. ### Idéal pour une vie familiale La résidence propose un cadre rassurant et convivial, parfaitement adapté aux familles à la recherche de stabilité et de confort. ### Un projet tourné vers l''avenir Prévue pour décembre 2027, cette résidence s''inscrit dans une vision moderne et un environnement en pleine évolution.', 'Casablanca', 'Victoria', 'Lotissement Annasr, Victoria, 27182 Casablanca', '27182', 'MA', NULL, NULL, 'immobilier', 'mixte', 'mixte', 'en_construction', 'en_commercialisation', 55, '2027-12', NULL, 'https://media.chridari.ma/d8c65c1b-c9c5-421f-8c88-03fea83d8248/images/01KPWW5TM6Q4QJQ6XPSZMJ3G4W-medium.jpg', $j$["https://media.chridari.ma/d8c65c1b-c9c5-421f-8c88-03fea83d8248/images/01KPWW5TM6Q4QJQ6XPSZMJ3G4W-medium.jpg", "https://media.chridari.ma/61e98403-71bc-408b-a955-f93e9f4e9c97/images/01KPWYQM0ZPB10RCX4G91TGFKM-medium.jpg", "https://media.chridari.ma/811395